#pragma once

// CIE color-space executors for nppi_color_conversion.h (package c4):
//   nppiRGBToXYZ / nppiXYZToRGB / nppiRGBToLUV / nppiLUVToRGB  (8u C3R/AC4R)
//
// Host-visible surface: the entry points are declared here and defined in
// nppi_color_space_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py
// (mpp_scripts/families/nppi_{rgb_to_xyz,xyz_to_rgb,rgb_to_luv,luv_to_rgb}.json).
//
// Semantics (baseline NVIDIA NPP 13.4, measured on the RTX 5090; the formulas
// are the ones documented in nppi_color_conversion.h and were verified
// element-exact against the library):
//   * RGBToXYZ / RGBToLUV: normalized RGB (x/255), XYZ matrix, then the
//     documented LUV derivation (cbrtf), scaled back to 8-bit with C float
//     truncation throughout.  L is clamped to [0,100], U to [-134,220] and
//     V to [-140,122] before the 8-bit scaling; XYZ clamps only at 1.0.
//   * XYZToRGB / LUVToRGB: normalized inverse matrices with the documented
//     clamps (XYZToRGB clamps only >1.0, LUVToRGB clamps to [0,1]) and
//     truncating 8-bit conversion.
//   * AC4 variants skip the alpha channel on output (the destination alpha is
//     left untouched); the source alpha is ignored.
//   * Validation order: null pointers (NPP_NULL_POINTER_ERROR) -> negative
//     width/height (NPP_SIZE_ERROR) -> empty ROI (NPP_NO_ERROR, no write,
//     short-circuits the step checks) -> step too small (NPP_STEP_ERROR) ->
//     AC4 only: step % 4 != 0 (NPP_NOT_EVEN_STEP_ERROR); C3 has no alignment
//     requirement.
//   * NVIDIA returns NPP_NO_ERROR for a negative step and launches a kernel
//     that walks out-of-bounds rows; mcMPP returns NPP_NO_ERROR without
//     launching (negative steps are not covered by goldens).  For AC4 a
//     negative step is still rejected when it is not 4-byte aligned, matching
//     the measured NPP_NOT_EVEN_STEP_ERROR.

#include "npp.h"
#include <cuda_runtime.h>

namespace nppi {
namespace color_space {

NppStatus rgbToXyz(const Npp8u *pSrc, int nSrcStep, Npp8u *pDst, int nDstStep, NppiSize oSizeROI, int channels,
                   cudaStream_t stream);

NppStatus xyzToRgb(const Npp8u *pSrc, int nSrcStep, Npp8u *pDst, int nDstStep, NppiSize oSizeROI, int channels,
                   cudaStream_t stream);

NppStatus rgbToLuv(const Npp8u *pSrc, int nSrcStep, Npp8u *pDst, int nDstStep, NppiSize oSizeROI, int channels,
                   cudaStream_t stream);

NppStatus luvToRgb(const Npp8u *pSrc, int nSrcStep, Npp8u *pDst, int nDstStep, NppiSize oSizeROI, int channels,
                   cudaStream_t stream);

}  // namespace color_space
}  // namespace nppi
